DROP TABLE IF EXISTS `quizzes`;
/*!40101 SET @saved_cs_client     = @@character_set_client */;
/*!50503 SET character_set_client = utf8mb4 */;
CREATE TABLE `quizzes` (
  `id` bigint unsigned NOT NULL AUTO_INCREMENT,
  `title` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NOT NULL,
  `title_hi` varchar(255) COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `slug` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NOT NULL,
  `description` text CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci,
  `description_hi` text COLLATE utf8mb4_unicode_ci,
  `meta_title` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `meta_title_hi` varchar(255) COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `meta_description` varchar(320) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `meta_description_hi` varchar(320) COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `meta_keywords` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `meta_keywords_hi` varchar(255) COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `primary_keyword` varchar(191) COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `primary_keyword_hi` varchar(191) COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `secondary_keywords` text COLLATE utf8mb4_unicode_ci,
  `secondary_keywords_hi` text COLLATE utf8mb4_unicode_ci,
  `search_intent` varchar(40) COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `seo_priority` varchar(4) COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `seo_h1` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `seo_h1_hi` varchar(255) COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `seo_intro` text CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci,
  `seo_intro_hi` text COLLATE utf8mb4_unicode_ci,
  `seo_content` longtext CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci,
  `seo_content_hi` longtext COLLATE utf8mb4_unicode_ci,
  `canonical_url` varchar(512) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `og_title` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `og_description` varchar(320) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `og_image` varchar(512) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `twitter_title` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `twitter_description` varchar(320) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `robots_index` tinyint(1) NOT NULL DEFAULT '1',
  `robots_follow` tinyint(1) NOT NULL DEFAULT '1',
  `schema_json` longtext CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci,
  `seo_score` tinyint unsigned DEFAULT NULL,
  `seo_updated_at` timestamp NULL DEFAULT NULL,
  `category_id` bigint unsigned DEFAULT NULL,
  `sub_category_id` bigint unsigned DEFAULT NULL,
  `quiz_type` enum('free','paid','subscription') CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NOT NULL DEFAULT 'free',
  `price` decimal(12,2) NOT NULL DEFAULT '0.00',
  `difficulty` enum('easy','medium','hard') CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NOT NULL DEFAULT 'medium',
  `total_questions` int unsigned NOT NULL DEFAULT '0',
  `question_limit` int unsigned NOT NULL DEFAULT '0',
  `time_limit` int unsigned NOT NULL DEFAULT '0' COMMENT 'minutes',
  `pass_percentage` tinyint unsigned NOT NULL DEFAULT '0',
  `marks_per_correct` decimal(8,2) NOT NULL DEFAULT '1.00',
  `negative_marking` decimal(8,2) NOT NULL DEFAULT '0.00',
  `randomize_questions` tinyint(1) NOT NULL DEFAULT '0',
  `randomize_options` tinyint(1) NOT NULL DEFAULT '0',
  `show_result` tinyint(1) NOT NULL DEFAULT '1',
  `show_correct_answers` tinyint(1) NOT NULL DEFAULT '1',
  `show_explanation` tinyint(1) NOT NULL DEFAULT '1',
  `status` enum('draft','published','archived') CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NOT NULL DEFAULT 'draft',
  `is_popular` tinyint(1) NOT NULL DEFAULT '0',
  `image` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `start_at` datetime DEFAULT NULL,
  `end_at` datetime DEFAULT NULL,
  `deleted_at` timestamp NULL DEFAULT NULL,
  `created_at` timestamp NULL DEFAULT NULL,
  `updated_at` timestamp NULL DEFAULT NULL,
  PRIMARY KEY (`id`),
  UNIQUE KEY `quizzes_slug_unique` (`slug`),
  KEY `quizzes_sub_category_id_foreign` (`sub_category_id`),
  KEY `quizzes_category_id_sub_category_id_index` (`category_id`,`sub_category_id`),
  KEY `quizzes_status_quiz_type_index` (`status`,`quiz_type`),
  KEY `quizzes_is_popular_index` (`is_popular`)
) ENGINE=InnoDB AUTO_INCREMENT=229 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;
