DROP TABLE IF EXISTS `bank_questions`;
/*!40101 SET @saved_cs_client     = @@character_set_client */;
/*!50503 SET character_set_client = utf8mb4 */;
CREATE TABLE `bank_questions` (
  `id` bigint unsigned NOT NULL AUTO_INCREMENT,
  `category_id` bigint unsigned DEFAULT NULL,
  `sub_category_id` bigint unsigned DEFAULT NULL,
  `question_type` enum('mcq_single','mcq_multi','true_false') CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NOT NULL DEFAULT 'mcq_single',
  `difficulty` enum('easy','medium','hard') CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NOT NULL DEFAULT 'medium',
  `question_text` text CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NOT NULL,
  `question_text_hi` text COLLATE utf8mb4_unicode_ci,
  `explanation` text CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci,
  `explanation_hi` text COLLATE utf8mb4_unicode_ci,
  `hint` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `hint_hi` varchar(255) COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `default_marks` decimal(8,2) NOT NULL DEFAULT '1.00',
  `correct_option_id` bigint unsigned DEFAULT NULL,
  `status` tinyint(1) NOT NULL DEFAULT '1',
  `deleted_at` timestamp NULL DEFAULT NULL,
  `created_at` timestamp NULL DEFAULT NULL,
  `updated_at` timestamp NULL DEFAULT NULL,
  PRIMARY KEY (`id`),
  KEY `bank_questions_sub_category_id_foreign` (`sub_category_id`),
  KEY `bank_questions_category_id_sub_category_id_index` (`category_id`,`sub_category_id`),
  KEY `bank_questions_difficulty_question_type_index` (`difficulty`,`question_type`)
) ENGINE=InnoDB AUTO_INCREMENT=10672 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;
