  `option_text` text CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NOT NULL,
  `option_text_hi` text COLLATE utf8mb4_unicode_ci,
  `is_correct` tinyint(1) NOT NULL DEFAULT '0',
  `sort_order` int unsigned NOT NULL DEFAULT '0',
  `created_at` timestamp NULL DEFAULT NULL,
  `updated_at` timestamp NULL DEFAULT NULL,
  PRIMARY KEY (`id`),
  KEY `bank_options_bank_question_id_is_correct_index` (`bank_question_id`,`is_correct`),
  CONSTRAINT `bank_options_bank_question_id_foreign` FOREIGN KEY (`bank_question_id`) REFERENCES `bank_questions` (`id`) ON DELETE CASCADE
) ENGINE=InnoDB AUTO_INCREMENT=42683 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;
