DROP TABLE IF EXISTS `question_import_rows`;
/*!40101 SET @saved_cs_client     = @@character_set_client */;
/*!50503 SET character_set_client = utf8mb4 */;
CREATE TABLE `question_import_rows` (
  `id` bigint unsigned NOT NULL AUTO_INCREMENT,
  `import_id` bigint unsigned NOT NULL,
  `row_number` int unsigned NOT NULL,
  `category_name` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `sub_category_name` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `category_id` bigint unsigned DEFAULT NULL,
  `sub_category_id` bigint unsigned DEFAULT NULL,
  `question` text CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci,
  `question_hi` text COLLATE utf8mb4_unicode_ci,
  `question_type` varchar(20) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `option_a` text CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci,
  `option_a_hi` text COLLATE utf8mb4_unicode_ci,
  `option_b` text CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci,
  `option_b_hi` text COLLATE utf8mb4_unicode_ci,
  `option_c` text CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci,
  `option_c_hi` text COLLATE utf8mb4_unicode_ci,
  `option_d` text CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci,
  `option_d_hi` text COLLATE utf8mb4_unicode_ci,
  `correct_answer` varchar(10) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `explanation` text CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci,
  `explanation_hi` text COLLATE utf8mb4_unicode_ci,
  `difficulty` varchar(20) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `validation_status` enum('pending','valid','invalid','duplicate','imported','failed','removed') CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NOT NULL DEFAULT 'pending',
  `validation_errors` json DEFAULT NULL,
  `duplicate_flag` tinyint(1) NOT NULL DEFAULT '0',
  `duplicate_question_id` bigint unsigned DEFAULT NULL,
  `bank_question_id` bigint unsigned DEFAULT NULL,
  `processed_at` timestamp NULL DEFAULT NULL,
  `created_at` timestamp NULL DEFAULT NULL,
  `updated_at` timestamp NULL DEFAULT NULL,
  PRIMARY KEY (`id`),
  KEY `question_import_rows_category_id_foreign` (`category_id`),
  KEY `question_import_rows_sub_category_id_foreign` (`sub_category_id`),
  KEY `question_import_rows_duplicate_question_id_foreign` (`duplicate_question_id`),
  KEY `question_import_rows_bank_question_id_foreign` (`bank_question_id`),
  KEY `question_import_rows_import_id_validation_status_index` (`import_id`,`validation_status`),
  KEY `question_import_rows_import_id_row_number_index` (`import_id`,`row_number`)
) ENGINE=InnoDB AUTO_INCREMENT=7 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;
