INSERT INTO `quiz_import_rows` VALUES (7676,18,2,'daily-current-affairs-19-august-2026','Daily Current Affairs 19 August 2026',NULL,'daily-current-affairs-19-august-2026','30 exam-oriented multiple-choice questions based on major current affairs and developments relevant on 19 August 2026.',NULL,'1',1,'2',2,'free',0.00,'medium',0,40,1.00,0.00,'published',0,'Which international observance is being marked on 19 August 2026 to honour humanitarian workers?',NULL,'mcq_single','World Humanitarian Day',NULL,'World Refugee Day',NULL,'International Peace Day',NULL,'World Health Day',NULL,'A','World Humanitarian Day is observed on 19 August to honour humanitarian workers and highlight their work in crises and disasters.',NULL,'easy','imported',NULL,0,NULL,NULL,NULL,210,10153,'2026-08-19 07:14:44','2026-08-19 07:14:44','2026-08-19 07:14:49'),(7677,18,3,'daily-current-affairs-19-august-2026','Daily Current Affairs 19 August 2026',NULL,'daily-current-affairs-19-august-2026','30 exam-oriented multiple-choice questions based on major current affairs and developments relevant on 19 August 2026.',NULL,'1',1,'2',2,'free',0.00,'medium',0,40,1.00,0.00,'published',0,'The first-ever Guide to Grasslands and Other Open Natural Ecosystems (ONEs) was unveiled during which UN session in August 2026?',NULL,'mcq_single','17th Session of UNCCD',NULL,'16th Session of UNEP',NULL,'15th Session of UNFCCC',NULL,'18th Session of UNESCO',NULL,'A','The guide was unveiled during the 17th Session of the UN Convention to Combat Desertification in Ulaanbaatar, Mongolia.',NULL,'medium','imported',NULL,0,NULL,NULL,NULL,210,10154,'2026-08-19 07:14:44','2026-08-19 07:14:44','2026-08-19 07:14:49'),(7678,18,4,'daily-current-affairs-19-august-2026','Daily Current Affairs 19 August 2026',NULL,'daily-current-affairs-19-august-2026','30 exam-oriented multiple-choice questions based on major current affairs and developments relevant on 19 August 2026.',NULL,'1',1,'2',2,'free',0.00,'medium',0,40,1.00,0.00,'published',0